def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--extract-wg-socks",
        metavar="DIR",
        help="Extract embedded wg-socks Go sources to DIR and exit",
    )
    parser.add_argument(
        "--repo-root",
        default=".",
        help="Path to RustDesk repository root (default: current directory)",
    )
    parser.add_argument(
        "--skip-rust-tray",
        action="store_true",
        help="Skip src/tray.rs patch (for macOS Flutter-only builds keeping Rust core untouched)",
    )
    args = parser.parse_args()

    if args.extract_wg_socks:
        extract_wg_socks(pathlib.Path(args.extract_wg_socks))
        return

    apply_patches(pathlib.Path(args.repo_root).resolve(), skip_rust_tray=args.skip_rust_tray)
    print("[done] all PocketDesk v3.0 patches applied successfully.")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"[ERROR] {exc}", file=sys.stderr)
        sys.exit(1)
